{"code_block": "import itertools
S = ['a','b','c','d','e']
op = {
    'a': {'a':'a','b':'b','c':'c','d':'b','e':'d'},
    'b': {'a':'b','b':'c','c':'a','d':'e','e':'c'},
    'c': {'a':'c','b':'a','c':'b','d':'b','e':'a'},
    'd': {'a':'b','b':'e','c':'b','d':'e','e':'d'},
    'e': {'a':'d','b':'b','c':'a','d':'d','e':'c'}
}
noncomm_unordered = []
for x,y in itertools.combinations(S,2):
    if op[x][y] != op[y][x]:
        noncomm_unordered.append((x,y, op[x][y], op[y][x]))
print(noncomm_unordered)", "sandbox_id": "idf308v7yyhgqxpjex350-6532622b"}
